// src/modules/assistant/assistant.module.ts
import { FastifyPluginAsync } from 'fastify';
import assistantRoutes from './assistant.routes';
import multipart from '@fastify/multipart';

const assistantModule: FastifyPluginAsync = async (fastify) => {
  // Registrar multipart para upload de áudio
  await fastify.register(multipart, {
    limits: {
      fileSize: 10 * 1024 * 1024, // 10MB max
    },
  });

  await fastify.register(assistantRoutes);
};

export default assistantModule;
export { assistantModule };
















